## Insert an item into a collection using data options

```javascript
import wixData from 'wix-data';

// ...

let toInsert = {
  "_id":          "00001",
  "title":        "Mr.",
  "first_name":   "John",
  "last_name":    "Doe"
};

let options = {
  "suppressAuth": true,
  "suppressHooks": true
};

wixData.insert("myCollection", toInsert, options)
  .then((item) => {
    console.log(item); //see item below
  })
  .catch((err) => {
  console.log(err);
  });

